// <video-player> — the themed wrapper over the SHIPPED wavelet player.
//
// Wavelet's reinvention: COMPOSITION-AS-SOURCE video. The composition (a
// <gm-doc> tree of <gm-timeline>/<gm-track>/<gm-clip>/<gm-scene>/… data
// elements, or plain HTML+CSS @keyframes) IS the source the player renders —
// preview ≡ render — and export is an IN-GUEST encode brokered through the
// Dock. This element does NOT reimplement any of that. It wraps the wavelet
// runtime (`desktop/static/wavelet/wavelet-runtime.js`, the `gm-doc`/`gm-data`
// custom elements) in a token-themed shell with a variant transport, and
// exposes play / pause / seek / export over the runtime's own API.
//
// The wavelet runtime auto-registers `gm-doc` on import (idempotent, like our
// define()). We import it lazily from `runtime-src` (default: the shipped
// path) so a host that already loaded it pays nothing, and a workbook that
// never plays video never fetches it.
//
// Source resolution (composition-as-source first):
//   • `composition` attr / a slotted <gm-doc> / inner gm-* markup — inlined
//     directly; the player IS the renderer (no fetch, no iframe). Preferred.
//   • `src="…html"` (or a <video-source>) — fetched, then inlined the same
//     way, so preview still equals render.
//
// Theming: chrome is suppressed on the embedded gm-doc (`data-embedded`); we
// paint our own controls from --work-* tokens only. The composition stage keeps
// its native pixels (preview ≡ render); we letterbox-scale the box, never the
// content — mirroring the desktop WaveletPlayer.
//
// Usage:
//   <video-player controls poster="…">
//     <gm-doc fps="30" resolution="1280x720" duration="2.0s"> … </gm-doc>
//   </video-player>
//   <video-player src="reel.html" controls autoplay></video-player>
//   el.play(); el.pause(); await el.export();

import { WbElement, html, css, define } from "../../core/element.js";
import { ref, createRef } from "lit/directives/ref.js";
import { defineVariants, variantAttrs } from "../../core/variants.js";

// Default location of the shipped wavelet runtime. Override per-element with
// `runtime-src`, or globally via window.__WB_WAVELET_RUNTIME__.
const DEFAULT_RUNTIME =
  (typeof window !== "undefined" && window.__WB_WAVELET_RUNTIME__) ||
  "/wavelet/wavelet-runtime.js";

// One in-flight import per URL, shared across every <video-player> on the page.
const _runtimeLoads = new Map();
function loadWaveletRuntime(rawSrc) {
  if (typeof customElements !== "undefined" && customElements.get("gm-doc")) {
    return Promise.resolve(true); // already registered by the host
  }
  // Resolve a relative runtime-src against the DOCUMENT base, not this module —
  // authors point it at a page-relative path (e.g. ./wavelet/… or /wavelet/…).
  let src = rawSrc;
  try {
    if (typeof document !== "undefined") src = new URL(rawSrc, document.baseURI).href;
  } catch { /* keep rawSrc */ }
  if (!_runtimeLoads.has(src)) {
    _runtimeLoads.set(
      src,
      import(/* @vite-ignore */ src).then(
        () => true,
        (e) => {
          _runtimeLoads.delete(src);
          throw e;
        },
      ),
    );
  }
  return _runtimeLoads.get(src);
}

const VARIANTS = defineVariants({
  // visual weight of the player frame
  variant: { options: ["solid", "soft", "bare"], default: "solid" },
  // transport density
  size: { options: ["sm", "md", "lg"], default: "md" },
  // accent the controls paint with
  tone: { options: ["brand", "neutral"], default: "brand" },
  // how the composition fills its box
  fit: { options: ["contain", "cover"], default: "contain" },
});

export class WorkVideo extends WbElement {
  static variants = VARIANTS;
  static props = [
    ...variantAttrs(VARIANTS),
    "src",
    "composition",
    "poster",
    "controls",
    "autoplay",
    "loop",
    "runtime-src",
  ];

  static styles = css`
    :host { display: block; color: var(--work-fg); font-family: var(--work-font); }

    .frame {
      position: relative;
      display: flex; flex-direction: column;
      background: var(--work-surface);
      border: 1.5px solid var(--work-border);
      border-radius: var(--work-radius-lg);
      overflow: hidden;
      box-shadow: var(--work-shadow);
    }
    :host([variant="soft"]) .frame { background: var(--work-surface-soft); box-shadow: var(--work-shadow-sm); }
    :host([variant="bare"]) .frame { background: transparent; border-color: transparent; box-shadow: none; border-radius: var(--work-radius); }

    /* stage: native composition pixels, letterbox-scaled to fit. Checkerboard
       behind transparent compositions, like the desktop player. */
    .stage-wrap {
      position: relative;
      flex: 1 1 auto; min-height: 0;
      display: flex; align-items: center; justify-content: center;
      aspect-ratio: var(--_aspect, 16 / 9);
      background:
        repeating-conic-gradient(
          color-mix(in srgb, var(--work-fg) 5%, transparent) 0% 25%,
          transparent 0% 50%) 50% / 22px 22px,
        var(--work-bg);
      overflow: hidden;
    }
    .stage {
      flex: 0 0 auto;
      transform-origin: center center;
      background: var(--work-scrim);
    }
    :host([fit="cover"]) .stage-wrap { /* cover lets the scaler overflow-crop */ }

    /* the embedded composition: chrome suppressed; we own the transport */
    .stage ::slotted(gm-doc), .stage gm-doc { display: block; }

    .poster {
      position: absolute; inset: 0;
      width: 100%; height: 100%; object-fit: cover;
      cursor: pointer;
    }
    .bigplay {
      position: absolute; inset: 0; margin: auto;
      width: 64px; height: 64px;
      display: grid; place-items: center;
      border: none; border-radius: var(--work-radius-pill);
      background: color-mix(in srgb, var(--work-brand) 88%, transparent);
      color: var(--work-on-brand);
      font-size: var(--work-glyph-sm); cursor: pointer;
      box-shadow: var(--work-shadow);
      transition: transform var(--work-dur) var(--work-ease);
    }
    .bigplay:hover { transform: scale(1.06); }

    .status {
      position: absolute; inset: 0;
      display: grid; place-items: center; padding: var(--work-space-4);
      text-align: center;
      color: var(--work-fg-muted); font-size: var(--work-text-sm);
      font-family: var(--work-font-mono);
    }
    .status.err { color: var(--work-err); white-space: pre-wrap; }

    /* transport — tokens only */
    .transport {
      flex: 0 0 auto;
      display: flex; align-items: center; gap: var(--work-space-2);
      padding: var(--work-space-2) var(--work-space-3);
      border-top: 1.5px solid var(--work-border);
      background: var(--work-surface);
      --_a: var(--work-brand); --_ink: var(--work-on-brand);
    }
    :host([tone="neutral"]) .transport { --_a: var(--work-fg); --_ink: var(--work-surface); }
    :host([variant="soft"]) .transport { background: var(--work-surface-soft); }
    :host([variant="bare"]) .transport { background: transparent; border-top-color: var(--work-border); }

    .transport button {
      appearance: none; cursor: pointer;
      height: 30px; min-width: 30px; padding: 0 var(--work-space-2);
      display: inline-flex; align-items: center; justify-content: center;
      border: 1.5px solid var(--work-border-strong);
      border-radius: var(--work-radius-sm);
      background: var(--work-surface); color: var(--work-fg);
      font-family: var(--work-font); font-size: var(--work-text-sm); font-weight: 600;
      line-height: 1;
      transition: border-color var(--work-dur) var(--work-ease), background var(--work-dur) var(--work-ease);
    }
    .transport button:hover:not(:disabled) { border-color: var(--_a); background: var(--work-brand-soft); }
    .transport button:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--work-ring); }
    .transport button:disabled { opacity: 0.45; cursor: default; }
    .play { color: var(--_a); font-weight: 700; }

    :host([size="sm"]) .transport { padding: var(--work-space-1) var(--work-space-2); }
    :host([size="sm"]) .transport button { height: 26px; min-width: 26px; }
    :host([size="lg"]) .transport { padding: var(--work-space-3) var(--work-space-4); }
    :host([size="lg"]) .transport button { height: 34px; min-width: 34px; font-size: var(--work-text); }

    .scrub {
      flex: 1 1 auto; min-width: 40px;
      accent-color: var(--_a); cursor: pointer;
    }
    .time, .frames {
      font-family: var(--work-font-mono); font-size: var(--work-text-sm);
      color: var(--work-fg-muted); white-space: nowrap;
    }
    .export { margin-left: auto; }
    .export.busy { opacity: 0.6; pointer-events: none; }
  `;

  // ---- lifecycle ----------------------------------------------------------

  constructor() {
    super();
    this._doc = null; // the embedded <gm-doc>
    this._ready = false;
    this._playing = false;
    this._raf = 0;
    this._status = null; // {kind:'load'|'error', msg}
    this._exporting = false;
    // refs to the live transport widgets (set by Lit after each render)
    this._stageRef = createRef();
    this._scrubRef = createRef();
    this._timeRef = createRef();
    this._framesRef = createRef();
    this._playRef = createRef();
  }

  connectedCallback() {
    super.connectedCallback();
    this._boot();
  }

  disconnectedCallback() {
    super.disconnectedCallback();
    cancelAnimationFrame(this._raf);
    this._raf = 0;
    try { this._doc?.pause?.(); } catch {}
  }

  // Only re-boot on source/runtime changes; cosmetic attrs just re-render. Lit
  // already re-renders on any reactive-property change; here we additionally
  // re-boot when the SOURCE changes.
  attributeChangedCallback(name, oldV, newV) {
    super.attributeChangedCallback(name, oldV, newV);
    if (!this.isConnected) return;
    if (["src", "composition", "runtime-src"].includes(name) && oldV !== newV) {
      this._boot();
    }
  }

  // After every Lit render: re-attach the cached gm-doc into the (new) stage
  // node and re-sync transport. update() rewrites the shadow tree, so the doc
  // must be re-homed — but the gm-doc element itself is preserved (never torn
  // down), so the player keeps running across theme/variant changes.
  updated() {
    if (this._doc) {
      const stage = this._stageRef.value;
      if (stage && this._doc.parentNode !== stage) stage.appendChild(this._doc);
      this._scaleStage();
      this._syncTransport();
    }
  }

  // ---- source resolution (composition-as-source) --------------------------

  /** Inline composition markup from, in order: `composition` attr, a slotted/
   *  child <gm-doc> or gm-* markup, else null (meaning: fetch `src`). */
  _inlineSource() {
    const attr = this.attr("composition");
    if (attr && attr.trim()) return attr;
    // A <video-source composition="…"> child (declarative form).
    const srcEl = this.querySelector("video-source[composition]");
    if (srcEl) {
      const c = srcEl.getAttribute("composition");
      if (c && c.trim()) return c;
    }
    // A slotted/child <gm-doc> authored directly inside <video-player>; move it
    // into the shadow stage.
    const child = this.querySelector("gm-doc");
    if (child) return child.outerHTML;
    return null;
  }

  /** The src to fetch when no inline composition is present. */
  _srcUrl() {
    const direct = this.attr("src");
    if (direct) return direct;
    const srcEl = this.querySelector("video-source[src]");
    return srcEl ? srcEl.getAttribute("src") : null;
  }

  async _boot() {
    cancelAnimationFrame(this._raf);
    this._ready = false;
    this._playing = false;
    this._doc = null;
    this._status = { kind: "load", msg: "Loading composition…" };
    this.requestUpdate();

    let markup = this._inlineSource();
    try {
      if (!markup) {
        const url = this._srcUrl();
        if (!url) {
          // Nothing to play — themed placeholder (clean, on-brand).
          this._status = null;
          this.requestUpdate();
          return;
        }
        const res = await fetch(url);
        if (!res.ok) throw new Error(`fetch ${res.status} ${url}`);
        markup = await res.text();
      }

      const runtimeSrc = this.attr("runtime-src", DEFAULT_RUNTIME);
      const needsRuntime = /<gm-doc[\s>]/i.test(markup) || /^\s*<gm-/i.test(markup);
      if (needsRuntime) await loadWaveletRuntime(runtimeSrc);

      this._status = null;
      await this._mount(markup);
    } catch (e) {
      this._status = { kind: "error", msg: `wavelet: ${e?.message || e}` };
      this.requestUpdate();
    }
  }

  /** Place the composition into the shadow stage and wire transport to the
   *  gm-doc API. The composition is the renderer; we never re-render frames. */
  async _mount(markup) {
    // Ensure the .stage node exists before we mount into it.
    this.requestUpdate();
    await this.updateComplete;
    const stage = this._stageRef.value;
    if (!stage) return;

    // If the markup is a full <gm-doc …>…</gm-doc>, instantiate it directly.
    // If it's bare gm-* fragments, wrap in a gm-doc carrying our attrs.
    let frag = markup.trim();
    if (!/^<gm-doc[\s>]/i.test(frag)) {
      frag = `<gm-doc data-embedded>${frag}</gm-doc>`;
    }
    stage.innerHTML = frag;
    const doc = stage.querySelector("gm-doc");
    if (!doc) {
      this._status = { kind: "error", msg: "no <gm-doc> in composition" };
      this.requestUpdate();
      return;
    }
    // Suppress wavelet's own chrome — we paint the themed transport.
    doc.setAttribute("data-embedded", "");
    this._doc = doc;

    // gm-doc resolves its timeline in connectedCallback (already run on
    // innerHTML insert). Read metadata for the aspect + transport.
    queueMicrotask(() => {
      this._ready = true;
      this._applyAspect();
      this._scaleStage();
      this.requestUpdate();
      if (this.boolAttr("autoplay")) this.play();
    });
  }

  _applyAspect() {
    const w = this._doc?.resolved?.resolution?.width;
    const h = this._doc?.resolved?.resolution?.height;
    if (w && h) {
      this.style.setProperty("--_aspect", `${w} / ${h}`);
    }
  }

  /** Letterbox-scale the native-pixel stage to fit its box (preview ≡ render —
   *  scale the box, not the content). Mirrors WaveletPlayer.recomputeScale. */
  _scaleStage() {
    const stage = this._stageRef.value;
    const wrap = stage?.parentElement;
    const w = this._doc?.resolved?.resolution?.width;
    const h = this._doc?.resolved?.resolution?.height;
    if (!wrap || !stage || !w || !h) return;
    stage.style.width = `${w}px`;
    stage.style.height = `${h}px`;
    const aw = wrap.clientWidth, ah = wrap.clientHeight;
    if (!aw || !ah) return;
    const cover = this.attr("fit") === "cover";
    const s = cover ? Math.max(aw / w, ah / h) : Math.min(aw / w, ah / h, 1);
    stage.style.transform = `scale(${s})`;
  }

  // ---- public transport API (delegates to the wavelet runtime) ------------

  play() {
    if (!this._doc) return;
    this._doc.play();
    this._playing = true;
    this._tickLoop();
    this.requestUpdate();
    this.dispatchEvent(new CustomEvent("work-play", { bubbles: true }));
  }

  pause() {
    if (!this._doc) return;
    this._doc.pause();
    this._playing = false;
    cancelAnimationFrame(this._raf);
    this.requestUpdate();
    this.dispatchEvent(new CustomEvent("work-pause", { bubbles: true }));
  }

  toggle() {
    if (this._playing) this.pause();
    else this.play();
  }

  /** Seek to a frame (render-equal precision — wavelet seeks the clock). */
  seek(frame) {
    if (!this._doc) return;
    const total = this._doc.totalFrames || 1;
    const f = Math.max(0, Math.min(total - 1, Math.round(frame)));
    this._doc.seekFrame(f);
    this._syncTransport();
  }

  get currentFrame() { return this._doc?.currentFrame ?? 0; }
  get totalFrames() { return this._doc?.totalFrames ?? 0; }
  get fps() { return this._doc?.fps ?? 30; }
  get playing() { return this._playing; }

  /** Export — IN-GUEST encode via the Dock when a runtime is reachable;
   *  otherwise download the portable, self-contained composition .html (the
   *  SAME source the renderer consumes — preview ≡ render ≡ the file). Both
   *  honor wavelet's model: the artifact is its own source. */
  async export({ format = "mp4" } = {}) {
    if (this._exporting) return;
    const markup = this._currentMarkup();
    if (!markup) return;
    this._exporting = true;
    this.requestUpdate();
    this.dispatchEvent(new CustomEvent("work-export-start", { bubbles: true }));
    try {
      if (this.host.available("wavelet")) {
        // In-guest encode brokered through the Dock (render_seq.wasm + the
        // wasm encoder). The host returns a URL / handle to the rendered file.
        const out = await this.host.request("/wavelet/encode", {
          body: { composition: markup, format, fps: this.fps },
        });
        this.dispatchEvent(
          new CustomEvent("work-export", { bubbles: true, detail: { ...out, format } }),
        );
        return out;
      }
      // Degrade: portable HTML download (self-contained composition).
      const file = await this._downloadPortable(markup);
      this.dispatchEvent(
        new CustomEvent("work-export", { bubbles: true, detail: { file, format: "html" } }),
      );
      return { file, format: "html" };
    } catch (e) {
      this.dispatchEvent(
        new CustomEvent("work-export-error", { bubbles: true, detail: { error: String(e) } }),
      );
      throw e;
    } finally {
      this._exporting = false;
      this.requestUpdate();
    }
  }

  /** The live composition markup (what plays === what exports). */
  _currentMarkup() {
    if (this._doc) {
      // Re-serialize the gm-doc tree without our embed flag.
      const clone = this._doc.cloneNode(true);
      clone.removeAttribute("data-embedded");
      return clone.outerHTML;
    }
    return this._inlineSource();
  }

  /** Inline the wavelet runtime so the downloaded .html plays standalone. */
  async _downloadPortable(markup) {
    const runtimeSrc = this.attr("runtime-src", DEFAULT_RUNTIME);
    let runtime = "";
    try {
      const res = await fetch(runtimeSrc);
      if (res.ok) runtime = await res.text();
    } catch { /* fall through — markup is still valid with an external runtime */ }
    const doc =
      `<!doctype html><html><head><meta charset="utf-8">` +
      (runtime ? `<script type="module">${runtime}<\/script>` : "") +
      `</head><body style="margin:0;background:#000">${markup}</body></html>`;
    const blob = new Blob([doc], { type: "text/html" });
    const url = URL.createObjectURL(blob);
    const name = (this.attr("src") || "composition").split("/").pop().replace(/\.html?$/i, "") + ".html";
    const a = document.createElement("a");
    a.href = url; a.download = name;
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return name;
  }

  // ---- transport tick -----------------------------------------------------

  _tickLoop() {
    cancelAnimationFrame(this._raf);
    const step = () => {
      if (!this._playing) return;
      // wavelet ended? (currentFrame stuck at end)
      if (this._doc && this._doc.currentFrame >= this._doc.totalFrames - 1) {
        if (this.boolAttr("loop")) {
          this._doc.seekFrame(0);
          this._doc.play();
        } else {
          this._playing = false;
          this._syncTransport();
          this.dispatchEvent(new CustomEvent("work-ended", { bubbles: true }));
          return;
        }
      }
      this._syncTransport();
      this._raf = requestAnimationFrame(step);
    };
    this._raf = requestAnimationFrame(step);
  }

  /** Update only the transport widgets without re-mounting the composition. */
  _syncTransport() {
    if (!this._doc) return;
    const scrub = this._scrubRef.value;
    const time = this._timeRef.value;
    const frames = this._framesRef.value;
    const play = this._playRef.value;
    const cur = this._doc.currentFrame, total = this._doc.totalFrames, fps = this._doc.fps;
    if (scrub) { scrub.max = String(Math.max(0, total - 1)); scrub.value = String(cur); }
    if (time) time.textContent = `${fmt(cur, fps)} / ${fmt(total, fps)}`;
    if (frames) frames.textContent = `f ${cur}/${Math.max(0, total - 1)} · ${fps}fps`;
    if (play) play.textContent = this._playing ? "❚❚" : "▶";
  }

  // ---- render -------------------------------------------------------------

  render() {
    const controls = this.boolAttr("controls");
    const poster = this.attr("poster");
    const showPoster = poster && !this._playing && !this._doc;
    const status = this._status;

    const overlay = showPoster
      ? html`<img class="poster" src=${poster} alt="" @click=${() => this.toggle()} /><button class="bigplay" aria-label="Play" @click=${() => this.toggle()}>▶</button>`
      : status
        ? html`<div class="status ${status.kind === "error" ? "err" : ""}">${status.msg}</div>`
        : !this._doc && !showPoster
          ? html`<div class="status">No composition. Set <code>composition</code>, <code>src</code>, or slot a &lt;gm-doc&gt;.</div>`
          : "";

    const stage = html`<div class="stage-wrap"><div class="stage" ${ref(this._stageRef)}></div>${overlay}</div>`;

    const transport = controls
      ? html`<div class="transport">
           <button class="play" aria-label="Play/Pause" @click=${() => this.toggle()} ${ref(this._playRef)}>${this._playing ? "❚❚" : "▶"}</button>
           <button class="step-back" aria-label="Previous frame" title="Previous frame" @click=${() => this.seek(this.currentFrame - 1)}>⟨</button>
           <button class="step-fwd" aria-label="Next frame" title="Next frame" @click=${() => this.seek(this.currentFrame + 1)}>⟩</button>
           <input class="scrub" type="range" min="0" max="0" step="1" value="0" aria-label="Scrub timeline" @input=${(e) => this.seek(Number(e.target.value))} ${ref(this._scrubRef)} />
           <span class="time" ${ref(this._timeRef)}>0:00 / 0:00</span>
           <span class="frames" ${ref(this._framesRef)}>f 0/0</span>
           <button class="export ${this._exporting ? "busy" : ""}" title="Export (in-guest encode, or portable .html)" @click=${() => { void this.export(); }}>${this._exporting ? "…" : "Export ↓"}</button>
         </div>`
      : "";

    return html`<div class="frame">${stage}${transport}</div>`;
  }
}

function fmt(frame, fps) {
  const s = Math.max(0, frame) / (fps || 30);
  const m = Math.floor(s / 60);
  const sec = Math.floor(s % 60);
  return `${m}:${String(sec).padStart(2, "0")}`;
}

define("video-player", WorkVideo);

// WbElement — the base for every <wb-*> element, re-based onto Lit.
//
// Lit is the FLOOR's engine now (the approved adoption pass): surgical template
// updates instead of an innerHTML nuke, while every workponents convention is
// preserved so the rest of the library migrates mechanically. Lit is loaded as a
// bare specifier ("lit") — buildless via an import map in the demos, a peer dep
// for SDK consumers (see README / demo/lit-foundation.html). No bundler, no
// `bun install`.
//
// Conventions (unchanged — the whole library follows these):
//   • Shadow DOM (open) for style isolation; --work-* tokens inherit through it.
//   • `static styles` = the component CSS as a Lit `css``` CSSResult (was a
//     string). Use ONLY var(--work-*). Variants targeted via :host([name="value"]).
//   • `render()` returns a Lit `html``` TemplateResult (was a string) — surgical
//     updates, no innerHTML rewrite.
//   • `static props` = reflected attributes that re-render on change (variants,
//     state). They are mapped to Lit reactive properties automatically.
//   • `static variants` defaults are reflected on connect (before first paint) so
//     :host([name="value"]) selectors always match.
//   • Capability is reached through `this.host` (the Dock seam), never hardcoded.
//   • Register with `define()` (idempotent — safe to load twice).
//
// `attr()` / `boolAttr()` helpers are preserved for elements that read attributes
// directly in render(). Re-exports `html` + `css` so domain files import the whole
// authoring surface from one place:
//   import { WbElement, html, css, define } from "../core/element.js";

import { LitElement, html, css } from "lit";
import { getHost } from "./host.js";

export { html, css };

export class WbElement extends LitElement {
  /** @type {import("lit").CSSResult} component CSS — override with css``; use only var(--work-*) */
  static styles = css``;

  /** @type {string[]} reflected attributes that trigger a re-render */
  static props = [];

  // Register each subclass's `static props` as Lit reactive properties so an
  // attribute change fires attributeChangedCallback + re-renders (the old
  // observedAttributes contract). NOTE: a base-class `static get properties()` is
  // NOT honored — Lit's finalize() only reads each class's OWN `properties`. So we
  // hook finalize() and createProperty() per subclass instead. Reflect ONLY the
  // short variant enums (so el.variant = "soft" still matches :host([variant]));
  // never reflect data attributes like `rows`/`csv`/`query` (can be huge strings).
  static finalize() {
    super.finalize();
    const variants = this.variants || {};
    for (const name of this.props || []) {
      const key = this._propKey(name);
      // Skip names that already exist on the prototype as a method/getter (e.g. a
      // `variant(name)` helper, an `open()` method). Creating a reactive accessor
      // there THROWS in Lit dev mode ("declared as a reactive property but it's
      // actually declared as a value on the prototype"). The attribute is still
      // OBSERVED via observedAttributes below, so attribute changes still fire
      // attributeChangedCallback → the element's reload/requestUpdate runs.
      if (key in this.prototype) continue;
      this.createProperty(key, {
        type: String,
        attribute: name,
        reflect: Object.prototype.hasOwnProperty.call(variants, name),
      });
    }
  }

  // Guarantee every `static props` attribute is OBSERVED (the browser reads this
  // at customElements.define() time). This is the bulletproof half: even if Lit's
  // reactive-property finalize timing misses one, attribute changes still fire
  // attributeChangedCallback → the element's reload/requestUpdate handler runs.
  static get observedAttributes() {
    const base = super.observedAttributes || [];
    return Array.from(new Set([...base, ...(this.props || [])]));
  }

  // Attribute names may contain dashes; reactive-property keys must be identifiers.
  static _propKey(name) {
    return name.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  }

  /** The Dock/Host capability seam — local | runtime (RCP) | kernel. */
  get host() {
    return getHost();
  }

  /** Read an attribute with a default. */
  attr(name, fallback = null) {
    return this.hasAttribute(name) ? this.getAttribute(name) : fallback;
  }

  /** Read a boolean attribute (present = true). */
  boolAttr(name) {
    return this.hasAttribute(name);
  }

  /** Override: return the template (Lit `html```). */
  render() {
    return html`<slot></slot>`;
  }

  connectedCallback() {
    // Reflect default variants BEFORE Lit's first render so :host([name="value"])
    // selectors match the very first paint, even when the author sets only some
    // (e.g. tone without variant).
    const v = this.constructor.variants;
    if (v) {
      for (const [name, def] of Object.entries(v)) {
        if (!this.hasAttribute(name)) this.setAttribute(name, def.default);
      }
    }
    super.connectedCallback();
  }
}

/** Idempotent custom-element registration (safe across double-loads). */
export function define(name, ctor) {
  if (!customElements.get(name)) customElements.define(name, ctor);
  return ctor;
}

// The Host/Dock seam — one capability surface for every element.
//
// A workponent never hardcodes where a capability runs. It asks the Host, which
// resolves `local` (in-WASM / browser-native), `runtime` (a Workbooks runtime
// over RCP) per the platform-model — so the SAME element
// (e.g. <wb-table>) runs in-WASM locally or on the runtime tier for huge data,
// no code fork. Capability elements declare what they need; the Host provisions
// it (the same grant model toolkits use) and reports availability so the element
// degrades cleanly when a capability is absent (e.g. voice without a key).
//
// Phase 0: a minimal, portable seam (no Tauri/Svelte). When a runtime URL is
// configured it routes over fetch/WebSocket (mirroring desktop/src/lib/rcp);
// otherwise it serves local capabilities and reports the rest unavailable.

let _host = null;

export class WbHost {
  /** @param {{ runtimeUrl?: string|null, tenant?: string }} [opts] */
  constructor(opts = {}) {
    this.runtimeUrl = opts.runtimeUrl || null;
    this.tenant = opts.tenant || "local";
    this._caps = new Set(["local"]); // in-WASM/browser caps are always present
  }

  /** Is a capability reachable here? (elements gate UI on this) */
  available(cap) {
    return this._caps.has(cap) || (this.runtimeUrl != null && cap !== "voice");
  }

  /** Unary capability call — routed to the runtime when present. */
  async request(path, { method = "POST", body } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const res = await fetch(this.runtimeUrl.replace(/\/$/, "") + path, {
      method,
      headers: { "content-type": "application/json", "x-tenant": this.tenant },
      body: body != null ? JSON.stringify(body) : undefined,
    });
    if (!res.ok) throw new Error(`wb-host ${res.status} ${path}`);
    return res.json();
  }

  /** Streaming capability — a WebSocket to the runtime. */
  socket(path, { onMessage } = {}) {
    if (!this.runtimeUrl) throw new Error(`wb-host: no runtime for ${path}`);
    const url = this.runtimeUrl.replace(/^http/, "ws").replace(/\/$/, "") + path;
    const ws = new WebSocket(url);
    if (onMessage) ws.addEventListener("message", (e) => onMessage(e.data));
    return ws;
  }
}

/** Configure the shared Host (call once at app/workbook boot). */
export function configureHost(opts) {
  _host = new WbHost(opts);
  return _host;
}

/** The shared Host singleton (a local-only Host by default). */
export function getHost() {
  if (!_host) {
    // Honor a global hint (a workbook/desktop can set window.__WB_RUNTIME_URL__).
    const url = typeof window !== "undefined" ? window.__WB_RUNTIME_URL__ : null;
    _host = new WbHost({ runtimeUrl: url || null });
  }
  return _host;
}

// Variants — the cva-style contract for web components.
//
// Variants are REFLECTED ATTRIBUTES the component CSS targets via :host([...]).
// This util doesn't generate classes; it (1) declares the allowed values +
// defaults for an element (so authoring is typed/validated and the design-lint
// can check conformance), and (2) normalizes the live attribute, applying the
// default when unset or invalid. The actual styling lives in the component CSS:
//
//   static styles = `
//     :host([variant="solid"]) button { background: var(--work-brand); }
//     :host([size="sm"])      button { padding: var(--work-space-1) var(--work-space-2); }
//   `;
//
// Usage in an element:
//   static variants = defineVariants({
//     variant: { options: ["solid", "soft", "ghost"], default: "solid" },
//     size:    { options: ["sm", "md", "lg"],        default: "md" },
//     tone:    { options: ["brand", "neutral", "ok", "warn", "err"], default: "brand" },
//   });
//   // in render(): this.variant("variant") -> the resolved value

export function defineVariants(spec) {
  return spec;
}

/** Resolve a variant attribute on `el` to a valid value (default on miss). */
export function resolveVariant(el, spec, name) {
  const def = spec[name];
  if (!def) return el.getAttribute(name);
  const v = el.getAttribute(name);
  return def.options.includes(v) ? v : def.default;
}

/** Every variant attribute name an element declares (for observedAttributes). */
export function variantAttrs(spec) {
  return Object.keys(spec || {});
}

/** Design-lint helper: report any variant attr set to a non-allowed value. */
export function lintVariants(el, spec) {
  const bad = [];
  for (const [name, def] of Object.entries(spec || {})) {
    const v = el.getAttribute(name);
    if (v != null && !def.options.includes(v)) bad.push({ name, value: v, allowed: def.options });
  }
  return bad;
}
